#pragma once

#include <Arduino.h>

#include "board/e32r40t.hpp"
#include "managents/core/chime.hpp"
#include "managents/core/ports.hpp"

namespace managents::adapters {

/// core::SoundOutput on the board's speaker connector: an SC8002B amplifier
/// fed by the ESP32's DAC (GPIO26), switched by GPIO4 (active low). The
/// enclosure's speaker mount holds a 28 mm speaker behind the back grille;
/// without one the chime drives nothing, which is harmless.
///
/// A chime is a handful of square-wave cycles on the DAC, generated by
/// busy-waiting: it blocks the loop for at most about a quarter second, once
/// per transition, well under the 5 s task watchdog. Two patterns, one tone
/// for waiting and two for error, so they are tellable apart by ear.
class Speaker : public core::SoundOutput {
public:
    /// Levels the square wave swings between, around the DAC's mid point:
    /// a modest amplitude, so the chime stays behind the ambient noise.
    static constexpr int kLevelLow = 56;
    static constexpr int kLevelHigh = 200;

    void begin() {
        pinMode(board::pins::kAudioEnable, OUTPUT);
        digitalWrite(board::pins::kAudioEnable, LOW);  // active low: the amplifier runs
    }

    void play(core::Chime chime) override {
        switch (chime) {
            case core::Chime::Waiting:
                tone(660, 140);
                break;
            case core::Chime::Error:
                tone(880, 90);
                delay(40);
                tone(640, 110);
                break;
        }
    }

private:
    /// A square wave of `hertz` for `milliseconds`, DAC level to DAC level.
    void tone(int hertz, int milliseconds) {
        const int halfPeriodUs = 500000 / hertz;
        const uint32_t end = millis() + static_cast<uint32_t>(milliseconds);
        bool high = false;
        while (millis() < end) {
            dacWrite(board::pins::kAudioDac, high ? kLevelHigh : kLevelLow);
            high = !high;
            delayMicroseconds(halfPeriodUs);
        }
        dacWrite(board::pins::kAudioDac, 128);  // rest at the mid point, not at a rail
    }
};

}  // namespace managents::adapters
